WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device ORDER BY started_at DESC, id) AS rn FROM sessions) t WHERE rn = 1) SELECT s.id, s.customer_id, s.browser, s.rn, CASE WHEN browser RLIKE '^(Safari|Chrome)$' THEN 'EXTENDED' WHEN browser RLIKE '^(Firefox|Edge)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS browser_zone, (SELECT MIN(x.balance) FROM accounts x WHERE x.customer_id = s.customer_id) AS min_account_balance FROM ranked s ORDER BY min_account_balance DESC;
